// Pega a linha que o Montar registro preparou e entrega para o Data table.
const registro = $('Montar registro').first().json;
if (!registro.linha || typeof registro.linha !== 'object') {
  throw new Error('O Montar registro não devolveu a linha. Rode o Test step dele antes deste.');
}
return [{ json: registro.linha }];

// Recebe o pacote que o plugin do Figma enviou (variáveis + respostas ou pedido) e deixa no formato que os próximos nós usam.
const entrada = $input.first();
let corpo = entrada.json.body;
if (typeof corpo === 'string') corpo = corpo.trim() ? JSON.parse(corpo) : null;
if ((!corpo || !corpo.base) && entrada.binary) {
  const chave = Object.keys(entrada.binary)[0];
  if (chave) corpo = JSON.parse((await this.helpers.getBinaryDataBuffer(0, chave)).toString('utf8'));
}
if (!corpo || !corpo.base) {
  throw new Error('O pacote do plugin não chegou. No nó Webhook, confira se a opção Raw Body está ligada.');
}
if (!Object.keys(corpo.semantic?.light || {}).length) {
  throw new Error('Não achei a coleção semantic com o modo light. Coleções do arquivo: ' + (corpo.colecoes || []).join(', '));
}

return [{ json: {
  inicio: new Date().toISOString(),
  acao: corpo.acao,
  arquivo: corpo.arquivo,
  respostas: corpo.respostas || {},
  pedido: corpo.pedido || {},
  base: corpo.base,
  semantic: corpo.semantic,
  specific: corpo.specific || { light: {}, dark: {} },
  contagem: {
    base: Object.keys(corpo.base).length,
    semantic: Object.keys(corpo.semantic.light).length,
    specific: Object.keys(corpo.specific?.light || {}).length,
  },
} }];

// Lê o texto da documentação (arquivo .md no Google Drive) e limpa o que não é texto, para a IA seguir as diretrizes.
// A API do Figma não entrega o texto dos blocos de spec, por isso a fonte é o .md exportado da documentação.
const item = $input.first();
const chave = Object.keys(item.binary || {})[0];
if (!chave) throw new Error('O nó Ler documentação não trouxe arquivo. Confira se a Operation é Download e se o arquivo é o .md da documentação.');
const bruto = (await this.helpers.getBinaryDataBuffer(0, chave)).toString('utf8');
const documentacao = bruto
  .replace(/^\[image\d+\]:.*$/gm, '')        // imagens embutidas em base64
  .replace(/!\[[^\]]*\]\[[^\]]*\]/g, '')      // marcadores das imagens
  .replace(/\\([-#.()_*\[\]])/g, '$1')        // barras de escape do export do Docs
  .replace(/\*\*/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 150000);
if (documentacao.length < 1000) throw new Error(`Só vieram ${documentacao.length} caracteres. Confira se o arquivo baixado é o .md da documentação.`);
return [{ json: { documentacao, caracteres: documentacao.length } }];

// Confere em código a variável que o estagiário criou no Figma. A IA só entra depois, no que pede julgamento.
const t = $('Ler tokens').first().json;
const pedido = t.pedido;
const nome = String(pedido.variavel || '').trim();
const vClaro = t.specific.light[nome];
const vEscuro = t.specific.dark[nome] || {};
if (!vClaro) throw new Error(`A variável "${nome}" não está na coleção specific do arquivo enviado.`);

// A descrição da variável traz os seis rótulos: Uso, Não usar, Par, Flexibilidade, Situação, Valor
const rotulos = ['Uso', 'Não usar', 'Par', 'Flexibilidade', 'Situação', 'Valor'];
const desc = {};
const ordemLida = [];
for (const linha of String(vClaro.descricao).split('\n')) {
  const m = linha.match(/^\s*(Uso|Não usar|Par|Flexibilidade|Situação|Valor)\s*:\s*(.*)$/);
  if (m) { desc[m[1]] = m[2].trim(); ordemLida.push(m[1]); }
}

const proposta = {
  nome: nome.toLowerCase(),
  uso: desc['Uso'] || '',
  naoUsar: desc['Não usar'] || '',
  par: (desc['Par'] || '').split(/[,;]/).map(s => s.trim().toLowerCase()).filter(s => s && !/^[—–-]$/.test(s)),
  claro: vClaro.ref || '',
  escuro: vEscuro.ref || '',
  flexibilidade: desc['Flexibilidade'] || '',
  situacao: desc['Situação'] || '',
  linhaValor: desc['Valor'] || '',
  escopos: vClaro.escopos || [],
  porque: String(pedido.porque || '').trim(),
  projeto: String(pedido.projeto || t.arquivo || '').trim(),
  quemPropoe: String(pedido.quemPropoe || '').trim(),
  data: String(pedido.data || '').trim(),
};
const valores = { claro: vClaro.valor, escuro: vEscuro.valor };

const checagens = [];
const add = (id, teste, resultado, detalhe) => checagens.push({ id, teste, resultado, detalhe });

// R-01 Formato do nome: minúsculas, barra entre níveis, hífen dentro do nível; sublinhado só na casa decimal
const niveis = proposta.nome.split('/');
const composto = ['typography', 'shadow'].includes(niveis[0]);
const maxNiveis = composto ? 4 : 3;
const formatoOk = nome === proposta.nome
  && /^[a-z0-9_-]+(\/[a-z0-9_-]+)+$/.test(proposta.nome)
  && niveis.length <= maxNiveis
  && niveis.every(n => /^[a-z0-9]+([-_][a-z0-9]+)*$/.test(n));
add('R-01', 'Formato do nome', formatoOk ? 'passa' : 'falha',
  formatoOk ? `${niveis.length} níveis` : `Use minúsculas, barra entre níveis (no máximo ${maxNiveis}) e hífen dentro do nível. Recebido: "${nome}"`);

// R-02 Primeiro nível é uma propriedade do vocabulário
const propriedades = ['text', 'icon', 'background', 'border', 'space', 'radius', 'border-width', 'opacity', 'typography', 'shadow', 'data'];
const propriedade = niveis[0];
add('R-02', 'Propriedade do vocabulário', propriedades.includes(propriedade) ? 'passa' : 'falha',
  propriedades.includes(propriedade) ? propriedade : `"${propriedade}" não é propriedade. Use: ${propriedades.join(', ')}`);

// R-03 Sem o nome do projeto no nome do token
const semAcento = s => String(s).normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
const palavrasProjeto = semAcento(proposta.projeto).split(/[^a-z0-9]+/).filter(p => p.length >= 4);
const achouProjeto = palavrasProjeto.find(p => semAcento(proposta.nome).includes(p));
add('R-03', 'Sem o nome do projeto', achouProjeto ? 'falha' : 'passa',
  achouProjeto ? `O nome contém "${achouProjeto}", do nome do projeto` : '—');

// R-04 Palavra nova descreve o uso, nunca a aparência nem o componente (alerta)
const aparencia = ['red', 'blue', 'green', 'yellow', 'orange', 'purple', 'pink', 'gray', 'grey', 'black', 'white', 'sepia', 'dark', 'light', 'warm', 'cool', 'big', 'tiny', 'thick', 'thin'];
const componentes = ['button', 'btn', 'card', 'modal', 'menu', 'input', 'field', 'chip', 'badge', 'tab', 'toast', 'tooltip', 'header', 'footer', 'sidebar', 'navbar', 'dialog', 'table', 'list'];
const ruimNome = proposta.nome.split(/[\/-]/).filter(p => aparencia.includes(p) || componentes.includes(p));
add('R-04', 'Sem aparência nem componente no nome', ruimNome.length ? 'alerta' : 'passa',
  ruimNome.length ? `Palavras a revisar: ${ruimNome.join(', ')}` : '—');

// R-05 Não repete um token da Semântica
const naSemantica = proposta.nome in t.semantic.light;
add('R-05', 'Não repete a Semântica', naSemantica ? 'falha' : 'passa',
  naSemantica ? 'Já existe na Semântica: use esse token (pergunta 1)' : '—');

// R-06 Os dois modos apontam para a Base (nunca valor digitado, nunca Semântica)
for (const [modo, v] of [['Claro', vClaro], ['Escuro', vEscuro]]) {
  let r = 'passa', d = `${v.ref} = ${v.valor}`;
  if (!v.ref) { r = 'falha'; d = v.valor !== undefined ? `Valor digitado (${v.valor}). Aponte para uma variável da Base` : 'Modo vazio'; }
  else if (v.refColecao !== 'base') { r = 'falha'; d = `${v.ref} é da coleção ${v.refColecao}. Aponte para a Base`; }
  add('R-06', `${modo} aponta para a Base`, r, d);
}

// R-07 Contraste nos dois modos (WCAG 2.2 AA). No token não existe tamanho de texto, então texto é sempre 4,5:1.
function lum(hex) {
  const c = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map(v => (v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function contraste(a, b) {
  const [l1, l2] = [lum(a), lum(b)].sort((x, y) => y - x);
  return (l1 + 0.05) / (l2 + 0.05);
}
const minimo = n => {
  const p = n.split('/')[0];
  if (p === 'text') return 4.5;
  if (p === 'border' && /subtle/.test(n)) return 0;
  if (['icon', 'border', 'data'].includes(p)) return 3;
  return null;
};
const corDe = (n, modo) => (t.semantic[modo][n] || t.specific[modo][n] || {}).valor;
if (['text', 'icon', 'background', 'border', 'data'].includes(propriedade)) {
  const minha = { light: vClaro.valor, dark: vEscuro.valor };
  let pares = proposta.par;
  if (!pares.length) pares = propriedade === 'background' ? ['text/primary'] : ['background/canvas', 'background/surface'];
  const souFundo = propriedade === 'background';
  const linhas = [];
  let falhou = false, semDado = false, medidos = 0;
  for (const modo of ['light', 'dark']) {
    for (const outro of pares) {
      const a = minha[modo], b = corDe(outro, modo);
      if (!/^#[0-9A-F]{6}/i.test(a||'')||!/#[0-9A-F]6/i.test(b || '')) { semDado = true; continue; }
      const frente = souFundo ? outro : proposta.nome;
      const min = minimo(frente);
      if (min === null) continue;
      const valor = contraste(a, b);
      const ok = valor >= min;
      medidos++;
      if (!ok) falhou = true;
      linhas.push(`${modo === 'light' ? 'claro' : 'escuro'}: ${frente} × ${souFundo ? proposta.nome : outro} = ${valor.toFixed(2)}:1 (mínimo ${min}:1) ${ok ? 'passa' : 'FALHA'}`);
    }
  }
  if (!proposta.par.length) linhas.push(`Par vazio: conferi contra ${pares.join(' e ')}`);
  if (semDado) linhas.push('Algum par sem cor: conferir no Figma');
  add('R-07', 'Contraste nos dois modos', falhou ? 'falha' : medidos ? 'passa' : 'alerta', linhas.join(' · ') || 'Nenhum par para medir');
}

// R-08 Escopo igual ao do grupo (T-06)
// Lista da seção 10 (Prompt para configurar, "Escopo por grupo"), com os nomes da Plugin API
const escopoEsperado = {
  text: ['TEXT_FILL'], icon: ['SHAPE_FILL', 'STROKE_COLOR'], background: ['FRAME_FILL', 'SHAPE_FILL'],
  border: ['STROKE_COLOR'], data: ['FRAME_FILL', 'SHAPE_FILL', 'STROKE_COLOR'], space: ['GAP'],
  radius: ['CORNER_RADIUS'], 'border-width': ['STROKE_FLOAT'], opacity: ['OPACITY'],
};
const campoComposto = {
  'font-size': ['FONT_SIZE'], 'line-height': ['LINE_HEIGHT'], 'font-weight': ['FONT_WEIGHT'], 'letter-spacing': ['LETTER_SPACING'],
  'font-family': ['FONT_FAMILY'], 'offset-x': ['EFFECT_FLOAT'], 'offset-y': ['EFFECT_FLOAT'], blur: ['EFFECT_FLOAT'], spread: ['EFFECT_FLOAT'], color: ['EFFECT_COLOR'],
};
const esperado = composto ? campoComposto[niveis[niveis.length - 1]] : escopoEsperado[propriedade];
if (esperado) {
  const igual = esperado.length === proposta.escopos.length && esperado.every(e => proposta.escopos.includes(e));
  add('R-08', 'Escopo do grupo', igual ? 'passa' : 'falha',
    igual ? esperado.join(', ') : `Esperado: ${esperado.join(', ')}. No Figma: ${proposta.escopos.join(', ') || 'nenhum (ou todos)'}`);
} else {
  add('R-08', 'Escopo do grupo', 'alerta', `Para ${propriedade}, conferir o escopo no Figma`);
}

// R-09 Descrição com os seis rótulos, na ordem (T-07)
const faltamRotulos = rotulos.filter(r => !(r in desc));
const naOrdem = ordemLida.join('|') === rotulos.join('|');
add('R-09', 'Descrição com os seis rótulos', !faltamRotulos.length && naOrdem ? 'passa' : 'falha',
  faltamRotulos.length ? `Faltam: ${faltamRotulos.join(', ')}` : naOrdem ? '—' : `Ordem lida: ${ordemLida.join(', ')}`);

// R-10 Situação começa como Proposto
add('R-10', 'Situação: Proposto', /^proposto$/i.test(proposta.situacao) ? 'passa' : 'falha',
  `Na descrição: "${proposta.situacao || 'vazio'}"`);

// R-11 A linha Valor bate com as referências reais
const valorOk = proposta.claro && proposta.escuro && proposta.linhaValor.includes(proposta.claro) && proposta.linhaValor.includes(proposta.escuro);
add('R-11', 'Linha Valor igual à referência', valorOk ? 'passa' : 'falha',
  `Descrição: "${proposta.linhaValor || 'vazio'}" · Figma: ${proposta.claro || '?'} | ${proposta.escuro || '?'}`);

// R-12 Uso e Não usar falam do papel na interface, sem nome de componente (alerta)
const compPt = ['botão', 'botao', 'campo', 'cartão', 'cartao', 'card', 'menu', 'modal', 'input', 'button', 'chip', 'badge', 'aba', 'tooltip', 'toast'];
const textoDesc = semAcento(proposta.uso + ' ' + proposta.naoUsar);
const achados = compPt.filter(c => new RegExp(`\\b${semAcento(c)}\\b`).test(textoDesc));
add('R-12', 'Uso e Não usar sem componente', achados.length ? 'alerta' : 'passa',
  achados.length ? `Encontrei: ${achados.join(', ')}` : '—');

// Tokens que já existem com a mesma propriedade, para a IA responder a pergunta 1
const linhaUso = d => (String(d).split('\n').find(l => l.startsWith('Uso:')) || '').replace('Uso:', '').trim();
const candidatos = [];
for (const [colecao, mapa] of [['semantic', t.semantic], ['specific', t.specific]]) {
  for (const [n, v] of Object.entries(mapa.light)) {
    if (n === nome || n.split('/')[0] !== propriedade) continue;
    candidatos.push(`${n} (${colecao}) | claro: ${v.ref || v.valor} | escuro: ${mapa.dark[n]?.ref || mapa.dark[n]?.valor || '?'} | uso: ${linhaUso(v.descricao) || 'sem descrição'}`);
  }
}

// Específicos já aprovados em outros projetos (tabela registro_propostas), para a pergunta 3
const aprovados = $('Buscar registro').all().map(i => i.json)
  .filter(r => r.token && r.decisao === 'aprovado' && r.projeto !== proposta.projeto)
  .map(r => `${r.token} | projeto: ${r.projeto} | necessidade: ${r.necessidade || r.uso}`);

const falhas = checagens.filter(c => c.resultado === 'falha').length;
const alertas = checagens.filter(c => c.resultado === 'alerta').length;
const tabela = checagens.map(c => `${c.id} ${c.teste}: ${c.resultado.toUpperCase()} — ${c.detalhe}`).join('\n');

const contexto_ia = [
  'VARIÁVEL CRIADA NO FIGMA',
  `Nome: ${proposta.nome}`,
  `Claro: proposta.claro({vClaro.valor}) | Escuro: proposta.escuro({vEscuro.valor})`,
  `Escopo: ${proposta.escopos.join(', ') || 'nenhum'}`,
  'Descrição:', vClaro.descricao || '(vazia)',
  `Por que nenhum token serve: ${proposta.porque}`,
  `Projeto: ${proposta.projeto}`,
  '',
  `CHECAGENS EM CÓDIGO (${falhas} falhas, ${alertas} alertas)`,
  tabela,
  '',
  `TOKENS QUE JÁ EXISTEM COM A PROPRIEDADE "${propriedade}" (${candidatos.length})`,
  candidatos.slice(0, 80).join('\n') || 'nenhum',
  '',
  `ESPECÍFICOS APROVADOS EM OUTROS PROJETOS (${aprovados.length})`,
  aprovados.join('\n') || 'nenhum ainda',
].join('\n');

return [{ json: { proposta, valores, checagens, falhas, alertas, contexto_ia } }];

// Monta a linha do registro com a decisão da lead. O e-mail já guarda a decisão, então não sai documento para o Drive.
const c = $('Conferir regras').first().json;
const p = c.proposta;
const parecer = $('Parecer').first().json.text || '';
const decisao = $('Esperar decisão').first().json; // respostas do formulário da lead
const aprovado = decisao['Decisão'] === 'Aprovar';
const recado = String(decisao['Feedback'] || '').trim();
const hoje = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Fortaleza' }).replaceAll('-', '.'); // AAAA.MM.DD, como as versões (seção 08)
const pegar = rotulo => ((parecer.match(new RegExp(rotulo + ':\\s*(.+)', 'i')) || [])[1] || '').trim();
const recomendacao = (pegar('RECOMENDACAO').match(/aprovar|ajustar|recusar/i) || ['?'])[0].toLowerCase();
const necessidade = pegar('NECESSIDADE') || p.porque;

return [{ json: {
  linha: {
    data: hoje,
    projeto: p.projeto,
    token: p.nome,
    uso: p.uso,
    necessidade,
    claro: p.claro,
    escuro: p.escuro,
    falhas: c.falhas,
    alertas: c.alertas,
    recomendacao_ia: recomendacao,
    decisao: aprovado ? 'aprovado' : 'recusado',
    minutos_ate_decisao: Math.round((Date.now() - new Date($('Ler tokens').first().json.inicio)) / 60000),
    parecer,
    observacao: recado,
  },
} }];

// Monta o e-mail para a lead decidir em poucos segundos: o veredito primeiro, o que fazer em seguida,
// o que precisa de correção, o que passou e o parecer em perguntas e respostas. O e-mail é o registro.
const c = $('Conferir regras').first().json;
const p = c.proposta;
const parecer = $('Parecer').first().json.text || '';
const pegar = rotulo => ((parecer.match(new RegExp(rotulo + ':\\s*(.+)', 'i')) || [])[1] || '').trim();
const recomendacao = (pegar('RECOMENDACAO').match(/aprovar|ajustar|recusar/i) || ['?'])[0].toLowerCase();
const esc = s => String(s ?? '').replace(/[&<>]/g, x => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[x]);
// Nomes de token (ex.: brand-1/600, text/on-action-primary) em azul e negrito, para achar rápido
const tk = s => esc(s).replace(/\b[a-z][a-z0-9-]*(?:\/[a-z0-9_.-]+)+/gi, m => `<b style="color:#1d4ed8">${m}</b>`);
const falhas = c.checagens.filter(x => x.resultado === 'falha');
const alertas = c.checagens.filter(x => x.resultado === 'alerta');
const passaram = c.checagens.filter(x => x.resultado === 'passa');
const quem = p.quemPropoe || 'quem propôs';
const total = c.checagens.length;

// Veredito e próximo passo, em linguagem direta
const veredito = {
  aprovar: { cor: '#1b7f3b', titulo: 'Pode aprovar', frase: `As ${total} checagens passaram e nenhum token que já existe faz o mesmo papel.`, acao: `Clique em Decidir e escolha Aprovar. ${quem} recebe os próximos passos por e-mail.` },
  ajustar: { cor: '#9a6700', titulo: 'Precisa de ajuste', frase: `${falhas.length} de ${total} checagens falharam e ${alertas.length} pedem atenção.`, acao: `Clique em Decidir e escolha Reprovar. ${quem} recebe por e-mail o que corrigir; use o recado para orientar.` },
  recusar: { cor: '#b42318', titulo: 'Recomendo recusar', frase: `${falhas.length} de totalchecagensfalharam{pegar('PERGUNTA 1') && !/nenhum/i.test(pegar('PERGUNTA 1')) ? ', e um token que já existe parece servir' : ''}.`, acao: `Clique em Decidir, escolha Reprovar e explique o motivo no recado. O parecer abaixo ajuda.` },
}[recomendacao] || { cor: '#444', titulo: 'Sem recomendação', frase: 'A IA não deu uma recomendação clara.', acao: 'Leia o parecer e decida.' };

// O botão abre o formulário do nó Esperar decisão, onde a lead escolhe e deixa um recado
const formulario = $execution.resumeFormUrl;
const css = 'text-align:left;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#1e1e1e;max-width:560px';
const titulo = t => `<p style="margin:18px 0 6px;font-size:13px;color:#555;text-transform:uppercase;letter-spacing:.04em"><b>${t}</b></p>`;
const item = x => `<li style="margin:0 0 4px"><b>${esc(x.teste)}:</b> ${tk(x.detalhe)}</li>`;
const pergunta = (q, r) => r ? `<p style="margin:0 0 8px"><b>${q}</b><br>${tk(r)}</p>` : '';

const email_html = `<div style="${css}">
<p style="margin:0 0 4px;font-size:18px;color:${veredito.cor}"><b>${veredito.titulo}</b></p>
<p style="margin:0 0 12px">${esc(veredito.frase)}</p>
<p style="margin:0 0 12px;padding:10px 12px;background:#f4f5f7;border-left:3px solid ${veredito.cor}"><b>O que fazer:</b> ${esc(veredito.acao)}</p>

${titulo('O pedido')}
<p style="margin:0 0 4px"><b style="color:#1d4ed8">${esc(p.nome)}</b> · ${esc(p.projeto)} · proposto por ${esc(quem)}</p>
<p style="margin:0 0 4px"><b>Para que serve:</b> ${esc(p.uso) || 'não informado'}</p>
<p style="margin:0 0 4px"><b>Por que nenhum token serve, segundo quem propôs:</b> ${tk(p.porque)}</p>
<p style="margin:0 0 4px"><b>Aponta para:</b> ${tk(p.claro || 'nada')} no claro · ${tk(p.escuro || 'nada')} no escuro</p>

${falhas.length ? titulo(`Precisa corrigir (${falhas.length})`) + `<ul style="margin:0;padding-left:18px">${falhas.map(item).join('')}</ul>` : ''}
${alertas.length ? titulo(`Vale conferir (${alertas.length})`) + `<ul style="margin:0;padding-left:18px">${alertas.map(item).join('')}</ul>` : ''}
${titulo(`Passou (${passaram.length})`)}
<p style="margin:0;color:#555">${passaram.map(x => esc(x.teste)).join(' · ') || 'nenhuma checagem'}</p>

${titulo('Parecer da IA')}
${pergunta('Algum token que já existe resolve?', pegar('PERGUNTA 1'))}
${pergunta('A necessidade é só deste projeto?', pegar('PERGUNTA 2'))}
${pergunta('A mesma necessidade já apareceu em 3 ou mais projetos?', pegar('PERGUNTA 3'))}
${pergunta('O nome segue a regra?', pegar('NOME'))}
${pergunta('A descrição está completa?', pegar('DESCRIÇÃO') || pegar('DESCRICAO'))}
<a href="${formulario}" style="display:block;margin:20px 0 0;text-align:center;padding:12px 0;background:#2f9e58;color:#fff;text-decoration:none;border-radius:6px;font-weight:bold">Decidir e deixar recado</a>
<p style="margin:16px 0 0;font-size:12px;color:#777">A decisão e o recado ficam na tabela registro_propostas, e quem propôs recebe o resultado por e-mail.</p>
</div>`;

// Versão em texto, caso o Gmail mostre as tags em vez do layout
const email_texto = [
  `${veredito.titulo.toUpperCase()}: ${veredito.frase}`,
  `O que fazer: ${veredito.acao}`,
  '',
  `O pedido: ${p.nome} · ${p.projeto} · proposto por ${quem}`,
  `Para que serve: ${p.uso || 'não informado'}`,
  `Aponta para: ${p.claro || 'nada'} no claro · ${p.escuro || 'nada'} no escuro`,
  '',
  falhas.length ? `Precisa corrigir:\n${falhas.map(x => `- ${x.teste}: ${x.detalhe}`).join('\n')}` : '',
  alertas.length ? `Vale conferir:\n${alertas.map(x => `- ${x.teste}: ${x.detalhe}`).join('\n')}` : '',
  `Passou: ${passaram.map(x => x.teste).join(' · ')}`,
  '',
  `Algum token que já existe resolve? ${pegar('PERGUNTA 1')}`,
  `É só deste projeto? ${pegar('PERGUNTA 2')}`,
  `Já apareceu em 3 ou mais projetos? ${pegar('PERGUNTA 3')}`,
  '',
  `Decidir: ${formulario}`,
].filter(l => l !== '').join('\n');

const assunto = `Validação de token: ${p.nome} · ${p.projeto} · ${veredito.titulo}`;
return [{ json: { email_html, email_texto, assunto } }];

const APROVADOR = 'Jorge'; // nome de quem aprova, para a linha do Registro
// Monta o e-mail de retorno para quem propôs: o resultado, o recado da lead e o que fazer em seguida.
const c = $('Conferir regras').first().json;
const p = c.proposta;
const para = String($('Ler tokens').first().json.pedido.emailPropoe || '').trim();
if (!para) return []; // sem e-mail no pedido, não há para quem avisar
const linha = $('Montar registro').first().json.linha;
const aprovado = linha.decisao === 'aprovado';
const recado = linha.observacao;
const parecer = linha.parecer || '';
const pegar = rotulo => ((parecer.match(new RegExp(rotulo + ':\\s*(.+)', 'i')) || [])[1] || '').trim();
const esc = s => String(s ?? '').replace(/[&<>]/g, x => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[x]);
const tk = s => esc(s).replace(/\b[a-z][a-z0-9-]*(?:\/[a-z0-9_.-]+)+/gi, m => `<b style="color:#1d4ed8">${m}</b>`);
const nome = (p.quemPropoe || '').split(' ')[0];

// Seção 05: na cor, "claro | escuro"; na medida, a referência com px e rem (border-width só em px); no peso, o nome junto
const ehCor = /^#/.test(String(c.valores.claro));
const medida = (ref, v) => {
  if (p.nome.startsWith('border-width/')) return `ref({String(v).replace('.', ',')} px)`;
  if (p.nome.startsWith('opacity/') || /font-weight/.test(p.nome)) return `ref({v})`;
  return `ref({String(v).replace('.', ',')} px · ${String(+(v / 16).toFixed(4)).replace('.', ',')} rem)`;
};
const linhaValor = ehCor || typeof c.valores.claro !== 'number'
  ? `${p.claro} | ${p.escuro}`
  : p.claro === p.escuro ? medida(p.claro, c.valores.claro) : `${medida(p.claro, c.valores.claro)} | ${medida(p.escuro, c.valores.escuro)}`;
const descricao = [
  `Uso: ${p.uso}`, `Não usar: ${p.naoUsar}`, `Par: ${p.par.join(', ') || '—'}`,
  `Flexibilidade: ${p.flexibilidade || '—'}`, 'Situação: Em uso', `Valor: ${linhaValor}`,
].join('\n');
const registro = `${p.projeto} · ${p.nome} · ${p.uso} · ${linha.necessidade} · ${linha.data} · ${APROVADOR} · Em uso`;
const falhas = c.checagens.filter(x => x.resultado === 'falha');
const alertas = c.checagens.filter(x => x.resultado === 'alerta');

const cor = aprovado ? '#1b7f3b' : '#b42318';
const titulo = aprovado ? 'Seu token foi aprovado' : 'Seu token precisa de ajuste';
const frase = aprovado
  ? `${p.nome} pode entrar em uso no ${p.projeto}. Faltam três passos para fechar.`
  : `${p.nome} ainda não pode ser usado. Corrija os pontos abaixo e envie de novo pelo plugin.`;
const css = 'text-align:left;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#1e1e1e;max-width:560px';
const sub = t => `<p style="margin:18px 0 6px;font-size:13px;color:#555;text-transform:uppercase;letter-spacing:.04em"><b>${t}</b></p>`;
const bloco = t => `<pre style="margin:0 0 4px;padding:10px 12px;background:#f4f5f7;border-radius:6px;font-family:Consolas,monospace;font-size:13px;white-space:pre-wrap">${esc(t)}</pre>`;
const item = x => `<li style="margin:0 0 4px"><b>${esc(x.teste)}:</b> ${tk(x.detalhe)}</li>`;
const pergunta = (q, r) => r && !/^ok\.?$/i.test(r) ? `<p style="margin:0 0 8px"><b>q</b><br>{tk(r)}</p>` : '';

const passos = aprovado
  ? `${sub('O que fazer agora')}
<p style="margin:0 0 6px"><b>1. No Figma, troque a descrição da variável por esta:</b></p>${bloco(descricao)}
<p style="margin:12px 0 6px"><b>2. Registre esta linha em Específicos aprovados, no quadro Registro:</b></p>${bloco(registro)}
<p style="margin:12px 0 0"><b>3. Avise quem cuida do front-end</b> que o token entrou, para ele levar ao código.</p>`
  : `${falhas.length ? sub(`Precisa corrigir (${falhas.length})`) + `<ul style="margin:0;padding-left:18px">${falhas.map(item).join('')}</ul>` : ''}
${alertas.length ? sub(`Vale conferir (${alertas.length})`) + `<ul style="margin:0;padding-left:18px">${alertas.map(item).join('')}</ul>` : ''}
${sub('Por que, segundo o parecer')}
${pergunta('Algum token que já existe resolve?', pegar('PERGUNTA 1'))}
${pergunta('A necessidade é só deste projeto?', pegar('PERGUNTA 2'))}
${pergunta('O nome segue a regra?', pegar('NOME'))}
${pergunta('A descrição está completa?', pegar('DESCRIÇÃO') || pegar('DESCRICAO'))}
${sub('O que fazer agora')}
<p style="margin:0">Ajuste a variável no Figma, mantenha a Situação como Proposto e envie de novo pela aba Validar do plugin.${pegar('PERGUNTA 1') && !/nenhum/i.test(pegar('PERGUNTA 1')) ? ' Se um token que já existe serve, use ele e não precisa reenviar.' : ''}</p>`;

const email_html = `<div style="${css}">
<p style="margin:0 0 4px;font-size:18px;color:${cor}"><b>${titulo}</b></p>
<p style="margin:0 0 12px">${nome ? esc(nome) + ', ' : ''}${tk(frase)}</p>
${recado ? `<p style="margin:0 0 12px;padding:10px 12px;background:#f4f5f7;border-left:3px solid ${cor}"><b>Recado da lead:</b> ${esc(recado)}</p>` : ''}
${passos}
<p style="margin:16px 0 0;font-size:12px;color:#777">Proposta: ${esc(p.nome)} · ${esc(p.projeto)} · enviada em ${esc(p.data || linha.data)}</p>
</div>`;

const assunto = `${aprovado ? 'Token aprovado' : 'Token precisa de ajuste'}: ${p.nome} · ${p.projeto}`;
return [{ json: { para, assunto, email_html } }];
